// Yixlid Jailer
// status: planned
// requires: a static ability that makes cards outside the battlefield lose all abilities
// Cards in graveyards lose all abilities.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); (q.state().obj(affected).became.is_none() && q.state().obj(affected).zone.kind() == ZoneKind::Graveyard && true) && true }
planned_item!("a-static-ability-that-makes-cards-outside-the-battlefield-lose-all-abilities" => statics: loses_all_abilities(ability_0_affects, "Cards in graveyards lose all abilities.").everywhere());

